import {
  IsEnum,
  IsBoolean,
  IsNotEmpty,
  IsNumber,
  IsOptional,
  IsString,
  Min,
} from 'class-validator';
import { Type } from 'class-transformer';
import { MaxDecimalPlaces } from '../../utils/validation/max-decimal-places';
import { IsOptionalNotNull } from '../../utils/validation/optional';
import { CostingMethod, ItemType } from '../../utils/enum/enum';

export class CreateProductDto {
  // Generated by the server; any client value is ignored.
  @IsOptional()
  @IsString()
  @IsNotEmpty()
  code?: string;

  @IsOptional()
  @IsString()
  barcode?: string;

  @IsString()
  @IsNotEmpty()
  name: string;

  @IsString()
  @IsNotEmpty()
  categoryId: string;

  @IsString()
  @IsNotEmpty()
  primaryItemUnitId: string;

  // Default STOCK. Values: STOCK (مخزني) | SERVICE (خدمي)
  @IsOptionalNotNull()
  @IsEnum(ItemType)
  itemType?: ItemType;

  // Default WEIGHTED_AVERAGE (متوسط التكلفة المرجح)
  @IsOptionalNotNull()
  @IsEnum(CostingMethod)
  costingMethod?: CostingMethod;

  @Type(() => Number)
  @IsNumber()
  @MaxDecimalPlaces(4)
  @Min(0)
  retailPrice: number;

  @Type(() => Number)
  @IsNumber()
  @MaxDecimalPlaces(4)
  @Min(0)
  wholesalePrice: number;

  @Type(() => Number)
  @IsNumber()
  @MaxDecimalPlaces(4)
  @Min(0)
  bulkWholesalePrice: number;

  @IsOptionalNotNull()
  @Type(() => Number)
  @IsNumber()
  @MaxDecimalPlaces(4)
  @Min(0)
  reorderLimit?: number;

  @IsOptionalNotNull()
  @IsBoolean()
  hasExpiryDate?: boolean;
}
